-- Prisma's @default(uuid()) is generated by the Prisma client and is not a
-- database default. This trigger writes audit rows in SQL, so it must supply
-- the required identifier itself when closing a run's capacity extension.
CREATE OR REPLACE FUNCTION oic_7_close_capacity_extension_on_terminal_run() RETURNS trigger AS $$
DECLARE item RECORD;
BEGIN
  IF NEW."status" IS DISTINCT FROM OLD."status" AND NEW."status" IN ('EXECUTED','CANCELLED') THEN
    FOR item IN
      UPDATE "OicEvaluationCapacityExtension"
      SET "status" = 'CLOSED'
      WHERE "runId" = NEW."id" AND "status" = 'ACTIVE'
      RETURNING "id", "applicationId", "tenantId", "createdBy"
    LOOP
      INSERT INTO "OicAuditEvent" ("id","actorPrincipalId","applicationId","tenantId","action","targetType","targetId","metadata")
      VALUES (gen_random_uuid(), item."createdBy", item."applicationId", item."tenantId", 'evaluation.packet76.capacity_extension.closed',
        'evaluation-capacity-extension', item."id", jsonb_build_object('runId', NEW."id", 'reason', 'TERMINAL_RUN_CLOSURE'));
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
